import 'dart:convert';

import 'package:flutter/services.dart';

/// Bundled emoji table (Write 04 §20.1), generated by
/// `tool/unicode/gen_emoji.py` from emojibase-data (Unicode emoji 15.1).
///
/// Asset format (compact JSON):
///
/// ```json
/// {"version": "15.1",
///  "categories": [{"id": "smileys", "name": "Smileys & emotion", "icon": "😀"}],
///  "emoji": [["😀", "grinning face", ["grin"], 0, ["grinning"], 0]]}
/// ```
///
/// Per emoji: char, CLDR name, keywords (minus the name's own words),
/// category index, shortcodes, skin tones (`0` none, `1` derived by inserting
/// the modifier after the first code point, or a list of the five variants).
const emojiAssetKey = 'assets/emoji/emoji.json';

const _vs16 = 0xFE0F;

/// First skin tone modifier (U+1F3FB, light). Tone `n` is `0x1F3FA + n`.
const _skinToneBase = 0x1F3FA;

/// Names of the skin tones 0..5 (0 = default yellow).
const skinToneNames = [
  'Default',
  'Light',
  'Medium-light',
  'Medium',
  'Medium-dark',
  'Dark',
];

class EmojiCategory {
  const EmojiCategory({
    required this.id,
    required this.name,
    required this.icon,
  });

  final String id;
  final String name;

  /// Emoji shown on the category tab.
  final String icon;
}

class Emoji {
  Emoji({
    required this.char,
    required this.name,
    this.keywords = const [],
    this.shortcodes = const [],
    required this.category,
    bool derivedSkinTones = false,
    List<String>? skinToneVariants,
  }) : _derived = derivedSkinTones,
       _variants = skinToneVariants,
       _nameWords = _words(name),
       _lowerName = name.toLowerCase();

  final String char;

  /// CLDR short name ("grinning face").
  final String name;
  final List<String> keywords;
  final List<String> shortcodes;

  /// Index into [EmojiCatalog.categories].
  final int category;

  final bool _derived;
  final List<String>? _variants;
  final List<String> _nameWords;
  final String _lowerName;

  bool get hasSkinTones => _derived || _variants != null;

  /// This emoji with skin tone [tone] (0 = none, 1..5 = light..dark).
  /// Emoji without skin tones are returned unchanged.
  String withSkinTone(int tone) {
    if (tone < 1 || tone > 5 || !hasSkinTones) return char;
    final variants = _variants;
    if (variants != null) return variants[tone - 1];
    final runes = char.runes.toList();
    final rest = runes.sublist(1);
    if (rest.isNotEmpty && rest.first == _vs16) rest.removeAt(0);
    return String.fromCharCodes([runes.first, _skinToneBase + tone, ...rest]);
  }

  /// The five toned variants (empty without skin tones).
  List<String> get skinToneVariants => [
    if (hasSkinTones)
      for (var t = 1; t <= 5; t++) withSkinTone(t),
  ];

  @override
  String toString() => 'Emoji($char $name)';
}

List<String> _words(String s) => s
    .toLowerCase()
    .split(RegExp(r"[^\p{L}\p{N}']+", unicode: true))
    .where((w) => w.isNotEmpty)
    .toList();

class EmojiCatalog {
  EmojiCatalog._(this.version, this.categories, this.all) {
    for (final e in all) {
      _byCategory[e.category].add(e);
      _byChar[e.char] = e;
      _byChar.putIfAbsent(_stripVs(e.char), () => e);
      for (final v in e.skinToneVariants) {
        _byChar[v] = e;
      }
    }
  }

  /// Parses the asset JSON (see [emojiAssetKey]).
  factory EmojiCatalog.fromJson(String json) {
    final map = jsonDecode(json) as Map<String, dynamic>;
    final cats = [
      for (final c in map['categories'] as List)
        EmojiCategory(
          id: c['id'] as String,
          name: c['name'] as String,
          icon: c['icon'] as String,
        ),
    ];
    final emoji = <Emoji>[];
    for (final row in map['emoji'] as List) {
      final r = row as List;
      final skin = r.length > 5 ? r[5] : 0;
      final category = r[3] as int;
      if (category < 0 || category >= cats.length) continue;
      emoji.add(
        Emoji(
          char: r[0] as String,
          name: r[1] as String,
          keywords: [for (final k in r[2] as List) k as String],
          category: category,
          shortcodes: [for (final s in r[4] as List) s as String],
          derivedSkinTones: skin == 1,
          skinToneVariants: skin is List && skin.length == 5
              ? [for (final v in skin) v as String]
              : null,
        ),
      );
    }
    return EmojiCatalog._(
      map['version'] as String? ?? '',
      List.unmodifiable(cats),
      List.unmodifiable(emoji),
    );
  }

  static final _cache = Expando<Future<EmojiCatalog>>();

  /// Loads the bundled catalog once per [bundle] (default [rootBundle]).
  /// Call it lazily (when the picker opens); later calls return the cached
  /// catalog.
  static Future<EmojiCatalog> load([AssetBundle? bundle]) {
    final b = bundle ?? rootBundle;
    return _cache[b] ??= () async {
      try {
        final data = await b.load(emojiAssetKey);
        final text = utf8.decode(
          data.buffer.asUint8List(data.offsetInBytes, data.lengthInBytes),
        );
        return EmojiCatalog.fromJson(text);
      } catch (_) {
        _cache[b] = null;
        rethrow;
      }
    }();
  }

  /// Unicode emoji version of the data ("15.1").
  final String version;
  final List<EmojiCategory> categories;

  /// All emoji in catalog order.
  final List<Emoji> all;

  late final List<List<Emoji>> _byCategory = [
    for (var i = 0; i < categories.length; i++) <Emoji>[],
  ];
  final _byChar = <String, Emoji>{};

  List<Emoji> inCategory(int i) =>
      i < 0 || i >= _byCategory.length ? const [] : _byCategory[i];

  /// The emoji for [char], also when [char] is a skin-toned variant or lacks
  /// the emoji presentation selector (U+FE0F).
  Emoji? byChar(String char) => _byChar[char] ?? _byChar[_stripVs(char)];

  /// Emoji whose shortcode, name or keywords match [query], best first.
  ///
  /// Ranking: exact shortcode, exact name, shortcode prefix, name starting
  /// with the query, a name word starting with the query, keyword exact,
  /// keyword prefix, then substring matches. Several words must all match.
  /// Leading/trailing `:` are ignored (`:smile:`). Ties keep catalog order.
  List<Emoji> search(String query, {int limit = 50}) {
    final q = query.trim().toLowerCase().replaceAll(RegExp(r'^:+|:+$'), '');
    if (q.isEmpty || limit <= 0) return const [];
    final tokens = _words(q.replaceAll('_', ' '));
    final scored = <(int, int, Emoji)>[];
    for (var i = 0; i < all.length; i++) {
      final e = all[i];
      final s = _score(e, q, tokens);
      if (s != null) scored.add((s, i, e));
    }
    scored.sort((a, b) {
      final c = a.$1.compareTo(b.$1);
      return c != 0 ? c : a.$2.compareTo(b.$2);
    });
    return [for (final s in scored.take(limit)) s.$3];
  }

  static int? _score(Emoji e, String q, List<String> tokens) {
    if (e.shortcodes.contains(q)) return 0;
    if (e._lowerName == q) return 1;
    if (e.shortcodes.any((s) => s.startsWith(q))) return 2;
    if (e._lowerName.startsWith(q)) return 3;
    if (tokens.length > 1) {
      // Every word must prefix a name word, a keyword or a shortcode part.
      var allInName = true;
      for (final t in tokens) {
        final inName = e._nameWords.any((w) => w.startsWith(t));
        if (!inName) allInName = false;
        if (!inName &&
            !e.keywords.any((k) => k.startsWith(t)) &&
            !e.shortcodes.any(
              (s) => s.split('_').any((p) => p.startsWith(t)),
            )) {
          return null;
        }
      }
      return allInName ? 4 : 6;
    }
    if (e._nameWords.any((w) => w.startsWith(q))) return 4;
    if (e.keywords.contains(q)) return 5;
    if (e.keywords.any((k) => k.startsWith(q))) return 6;
    if (q.length >= 2 &&
        (e._lowerName.contains(q) || e.shortcodes.any((s) => s.contains(q)))) {
      return 7;
    }
    return null;
  }
}

String _stripVs(String s) => s.replaceAll('️', '');
